div.script:
(function(){
    var dobEl = document.getElementById('dobInput');
    var ageEl = document.getElementById('ageInput');
    if (!dobEl || !ageEl) return;

    function calcAge(dob) {
        var today = new Date();
        var birth = new Date(dob);
        var age = today.getFullYear() - birth.getFullYear();
        var m = today.getMonth() - birth.getMonth();
        if (m < 0 || (m === 0 && today.getDate() < birth.getDate())) age--;
        return age;
    }

    function calcDob(age) {
        var today = new Date();
        var year = today.getFullYear() - parseInt(age);
        var mm = String(today.getMonth() + 1).padStart(2, '0');
        var dd = String(today.getDate()).padStart(2, '0');
        return year + '-' + mm + '-' + dd;
    }

    dobEl.addEventListener('change', function(){
        if (this.value) {
            ageEl.value = calcAge(this.value);
        }
    });

    ageEl.addEventListener('input', function(){
        var v = parseInt(this.value);
        if (!isNaN(v) && v >= 0 && v <= 100) {
            dobEl.value = calcDob(v);
        }
    });
})();

function toggleBunnaFields(val) {
    var block = document.getElementById('bunnaFieldsBlock');
    if (block) {
        block.style.display = (val === 'yes') ? 'flex' : 'none';
    }
}

/* ---- Live Experience Calculator ---- */
function calcYearsBetween(startStr, endStr, isCurrent) {
    if (!startStr) return 0;
    var s = new Date(startStr);
    var e = (isCurrent || !endStr) ? new Date() : new Date(endStr);
    var diff = (e - s) / (1000 * 60 * 60 * 24 * 365.25);
    return diff > 0 ? Math.round(diff * 100) / 100 : 0;
}

function recalcExperienceCards() {
    var banking = 0, nonBanking = 0;

    /* Sum saved rows from table */
    var rows = document.querySelectorAll('.exp-saved-row');
    rows.forEach(function(row) {
        var sector = row.getAttribute('data-sector');
        var start = row.getAttribute('data-start');
        var end = row.getAttribute('data-end');
        var curr = row.getAttribute('data-current') === '1';
        var yrs = calcYearsBetween(start, end, curr);
        if (sector === 'banking') banking += yrs;
        else nonBanking += yrs;
    });

    /* Add current form entry (if user is filling it) */
    var formStart = document.querySelector('#addExpContainer [name="start_date"]');
    var formEnd = document.querySelector('#addExpContainer [name="end_date"]');
    var formCurrent = document.querySelector('#addExpContainer [name="is_current"]');
    var formSector = document.querySelector('#addExpContainer [name="sector_type"]');
    if (formStart && formStart.value) {
        var isCurr = formCurrent && formCurrent.checked;
        var formYrs = calcYearsBetween(formStart.value, formEnd ? formEnd.value : '', isCurr);
        var sec = formSector ? formSector.value : 'banking';
        if (sec === 'banking') banking += formYrs;
        else nonBanking += formYrs;
    }

    var total = banking + nonBanking;

    /* Update card displays */
    var elB = document.getElementById('cardBankingExp');
    var elN = document.getElementById('cardNonBankingExp');
    var elT = document.getElementById('cardTotalExp');
    if (elB) elB.innerHTML = banking.toFixed(2) + ' Yrs';
    if (elN) elN.innerHTML = nonBanking.toFixed(2) + ' Yrs';
    if (elT) elT.innerHTML = total.toFixed(2) + ' Yrs';
}

/* Attach listeners to experience form fields */
document.addEventListener('DOMContentLoaded', function() {
    var fields = ['start_date', 'end_date', 'is_current', 'sector_type'];
    fields.forEach(function(name) {
        var el = document.querySelector('#addExpContainer [name="' + name + '"]');
        if (el) el.addEventListener('change', recalcExperienceCards);
    });
    /* Initial calculation on page load */
    recalcExperienceCards();
});
